    url: p.link,
    wp_id: p.id,
    post_type: p.type,
    title,
    html,
    meta_description: stripTags(p.excerpt && p.excerpt.rendered).slice(0, 300),
    modified_gmt: p.modified_gmt ? `${p.modified_gmt}Z` : null,
