function truncateMarkdown(md, maxChars) {
  if (md.length <= maxChars) return [md, false];
  let cut = md.lastIndexOf('\n\n', maxChars);
  if (cut < maxChars * 0.6) cut = maxChars;
  return [md.slice(0, cut).trimEnd(), true];
}
// ---- akhir utilitas ----
// Markdown halaman internal: judul WordPress jadi satu-satunya H1, lalu isi konten yang sudah dibersihkan.
function buildPageMarkdown(p) {
  let body = stripMarkdownNoise(p.markdown || '', { trimH1: false });
  // Heading H1 di dalam konten diturunkan jadi H2 supaya H1 tetap satu (judul halaman).
  body = body.replace(/^#\s+/gm, '## ');
  return `# ${p.title}\n\n${body}`.trim();
}
// Satu baris per halaman untuk tabel seo_pages (outline, markdown utuh, jumlah chunk, hash).
const counts = {};
for (const it of $('✂️ Chunk + contextual header').all()) {
  counts[it.json.url] = (counts[it.json.url] || 0) + 1;
}

return $('📝 HTML → Markdown').all()
  .filter((it) => counts[it.json.url])
  .map((it) => {
    const p = it.json;
    const md = buildPageMarkdown(p);
    return {
      json: {
        url: p.url,
        wp_id: p.wp_id,
        post_type: p.post_type,
        title: p.title,
        meta_description: p.meta_description,
        outline: formatOutline(extractOutline(md)),
        markdown: md,
        word_count: wordCount(md),
        chunk_count: counts[p.url],
        content_hash: p.content_hash,
        modified_gmt: p.modified_gmt,
      },
    };
  });
